const LEVEL3_EXTRA_STORIES = LEVEL3_EXTRA_STORIES_RAW.map((s,i)=>{
  const makeQuiz=([q,right,w1,w2,w3,why],j)=>{
    const a=(i*2+j+1)%4;
    const opts=[w1,w2,w3];opts.splice(a,0,right);
    return {q,opts,a,why};
  };
  return {...s,id:`lv3-new-${String(i+1).padStart(2,'0')}`,
    words:s.words.split(/\s+/),pages:s.pages.map(([en,zh])=>({en,zh})),
    quiz:s.quiz.map(makeQuiz)};
});
LEVEL3_STORIES.push(...LEVEL3_EXTRA_STORIES);
